function CoreGasEscapeChannelMaker.init() CoreGasEscapeChannelMaker.ironStock=14; CoreGasEscapeChannelMaker.bronzeStock=12; CoreGasEscapeChannelMaker.woodStock=12; CoreGasEscapeChannelMaker.leatherStock=8; CoreGasEscapeChannelMaker.silverStock=8; CoreGasEscapeChannelMaker.goldStock=6; CoreGasEscapeChannelMaker.jewelStock=4; CoreGasEscapeChannelMaker.pearlStock=4; CoreGasEscapeChannelMaker.productStock={}; CoreGasEscapeChannelMaker.buildings={}; CoreGasEscapeChannelMaker.maker=nil; CoreGasEscapeChannelMaker.activeMaking={}; CoreGasEscapeChannelMaker.totalProducts=0; CoreGasEscapeChannelMaker.dayTimer=0; print("[CoreGasEscapeChannelMaker] Royal Core Gas Escape Channel Maker System initialized (6 products, 4 buildings)") end
function CoreGasEscapeChannelMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; CoreGasEscapeChannelMaker.maker={name=n or ("Kanalnik "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kanalnik najet: %s (spretnost: %d)",CoreGasEscapeChannelMaker.maker.name,s),"success") end; return true end
function CoreGasEscapeChannelMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function CoreGasEscapeChannelMaker.build(id) local ok,e=CoreGasEscapeChannelMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(CoreGasEscapeChannelMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function CoreGasEscapeChannelMaker.getQualityBonus() local b=0; for _,bd in ipairs(CoreGasEscapeChannelMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function CoreGasEscapeChannelMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and CoreGasEscapeChannelMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and CoreGasEscapeChannelMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and CoreGasEscapeChannelMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and CoreGasEscapeChannelMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and CoreGasEscapeChannelMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and CoreGasEscapeChannelMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and CoreGasEscapeChannelMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and CoreGasEscapeChannelMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #CoreGasEscapeChannelMaker.buildings==0 then return false,"Potrebna kanalna delavnica" end; if not CoreGasEscapeChannelMaker.maker then return false,"Potreben kanalnik" end; return true end
function CoreGasEscapeChannelMaker.make(pt,qty) qty=qty or 1; local ok,e=CoreGasEscapeChannelMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then CoreGasEscapeChannelMaker.ironStock=CoreGasEscapeChannelMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then CoreGasEscapeChannelMaker.bronzeStock=CoreGasEscapeChannelMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then CoreGasEscapeChannelMaker.woodStock=CoreGasEscapeChannelMaker.woodStock-d.woodCost*qty end; if d.leatherCost then CoreGasEscapeChannelMaker.leatherStock=CoreGasEscapeChannelMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then CoreGasEscapeChannelMaker.silverStock=CoreGasEscapeChannelMaker.silverStock-d.silverCost*qty end; if d.goldCost then CoreGasEscapeChannelMaker.goldStock=CoreGasEscapeChannelMaker.goldStock-d.goldCost*qty end; if d.jewelCost then CoreGasEscapeChannelMaker.jewelStock=CoreGasEscapeChannelMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then CoreGasEscapeChannelMaker.pearlStock=CoreGasEscapeChannelMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if CoreGasEscapeChannelMaker.maker then t=math.max(1,t-math.floor(CoreGasEscapeChannelMaker.maker.skill/13)) end; table.insert(CoreGasEscapeChannelMaker.activeMaking,{id="coregasescapechannel_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function CoreGasEscapeChannelMaker.completeMaking(m) local q=1.0+(CoreGasEscapeChannelMaker.getQualityBonus()/100); if CoreGasEscapeChannelMaker.maker then q=q+(CoreGasEscapeChannelMaker.maker.skill/140) end; q=math.min(2.5,q); CoreGasEscapeChannelMaker.productStock[m.productType]=(CoreGasEscapeChannelMaker.productStock[m.productType] or 0)+m.quantity; CoreGasEscapeChannelMaker.totalProducts=CoreGasEscapeChannelMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if CoreGasEscapeChannelMaker.maker then CoreGasEscapeChannelMaker.maker.itemsMade=CoreGasEscapeChannelMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then CoreGasEscapeChannelMaker.maker.skill=math.min(100,CoreGasEscapeChannelMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kanal izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"coregasescapechannel.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function CoreGasEscapeChannelMaker.update(dt) if not _G.state then return end; CoreGasEscapeChannelMaker.dayTimer=CoreGasEscapeChannelMaker.dayTimer+dt; if CoreGasEscapeChannelMaker.dayTimer>=30 then CoreGasEscapeChannelMaker.dayTimer=0; for i=#CoreGasEscapeChannelMaker.activeMaking,1,-1 do local m=CoreGasEscapeChannelMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then CoreGasEscapeChannelMaker.completeMaking(m); table.remove(CoreGasEscapeChannelMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(CoreGasEscapeChannelMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if CoreGasEscapeChannelMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function CoreGasEscapeChannelMaker.getStats() return {ironStock=CoreGasEscapeChannelMaker.ironStock,bronzeStock=CoreGasEscapeChannelMaker.bronzeStock,woodStock=CoreGasEscapeChannelMaker.woodStock,leatherStock=CoreGasEscapeChannelMaker.leatherStock,silverStock=CoreGasEscapeChannelMaker.silverStock,goldStock=CoreGasEscapeChannelMaker.goldStock,jewelStock=CoreGasEscapeChannelMaker.jewelStock,pearlStock=CoreGasEscapeChannelMaker.pearlStock,productStock=CoreGasEscapeChannelMaker.productStock,numBuildings=#CoreGasEscapeChannelMaker.buildings,hasMaker=CoreGasEscapeChannelMaker.maker~=nil,makerName=CoreGasEscapeChannelMaker.maker and CoreGasEscapeChannelMaker.maker.name or "—",makerSkill=CoreGasEscapeChannelMaker.maker and CoreGasEscapeChannelMaker.maker.skill or 0,activeMaking=#CoreGasEscapeChannelMaker.activeMaking,totalProducts=CoreGasEscapeChannelMaker.totalProducts} end
